function drawBars(root,values){root.replaceChildren(...values.map(v=>{let n=make('i');n.style.height=v+'%';return n;}));}
function updatePeriod(){
 const d=data[period];$('#date-range').value=period;$('#scene-period').value=period;
 $('#metric-revenue').textContent=d.revenue;$('#scene-revenue').textContent=d.revenue;$('#scene-summary').textContent=d.revenue;
 $('#metric-conversations').textContent=d.conversations;$('#metric-sales').textContent=d.sales;
 ['revenue','conversations','sales'].forEach((k,i)=>$('#metric-'+k+'-change').textContent='↑ '+d.growth[i]);
 $('#scene-growth').textContent='↑ '+d.growth[0];$('.scene-chart-stat b').textContent='↑ '+d.growth[0];
 drawBars($('#revenue-chart'),d.bars);drawBars($('#scene-bars'),d.bars);
 $('#chart-start').textContent=(lang==='ru'?'День ':'Day ')+'1';$('#chart-end').textContent=(lang==='ru'?'День ':'Day ')+period;
}
function setTab(name,focus=false){
 if(!['overview','inbox','team'].includes(name))return;activeTab=name;
 $$('.panel',$('#demo-dialog')).forEach(x=>x.hidden=x.id!=='panel-'+name);
 $$('[data-tab]').forEach(b=>{const yes=b.dataset.tab===name;b.classList.toggle('active',yes);if(b.getAttribute('role')==='tab'){b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1;}});
 const hints={en:{overview:'Try changing the date range.',inbox:'Choose a chat and add a local message.',team:'Try the shift switches.'},ru:{overview:'Попробуй изменить период.',inbox:'Выбери чат и добавь сообщение в демо.',team:'Попробуй переключатели смен.'}};
 $('#demo-hint').textContent=hints[lang][name];if(focus)$('#tab-'+name).focus({preventScroll:true});
}
function setScene(name,clicked){
 activeScene=name;$$('[data-view]').forEach(n=>n.hidden=n.dataset.view!==name);
 let marked=false;$$('[data-scene-view]').forEach(b=>{const yes=clicked?b===clicked:!marked&&b.dataset.sceneView===name;if(yes)marked=true;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));});
}
function showToast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function conversations(){
 const r=$('#conversation-list');r.replaceChildren();contacts.forEach((c,i)=>{const b=make('button','conversation'+(i===contactIndex?' active':''));b.type='button';b.setAttribute('aria-pressed',String(i===contactIndex));const inf=make('span','conversation-info');inf.append(make('strong','',c.name),make('span','',c.preview[lang==='ru'?1:0]));b.append(make('span','avatar '+c.color,c.initials),inf);b.addEventListener('click',()=>selectContact(i));r.append(b);});
 $$('.preview-contact').forEach((b,i)=>{b.classList.toggle('active',i===contactIndex);b.setAttribute('aria-pressed',String(i===contactIndex));$('small',b).textContent=contacts[i].preview[lang==='ru'?1:0];});
}
function selectContact(i){contactIndex=i;conversations();chat();}
function chat(){
 const c=contacts[contactIndex];$('#chat-name').textContent=c.name;$('#chat-avatar').textContent=c.initials;$('#chat-avatar').className='avatar '+c.color;
 $('#preview-name').textContent=c.name;
 // Reuse the already embedded asset rather than performing any external request.
 $('#preview-avatar').src=$('.preview-contact[data-contact="'+contactIndex+'"] img').src;
 const full=$('#chat-log'),small=$('#preview-chat-log');full.replaceChildren(make('span','chat-date',lang==='ru'?'Сегодня · демо-переписка':'Today · fictional conversation'));small.replaceChildren();
 const msgs=[...c.messages.map((a,i)=>({text:a[lang==='ru'?1:0],out:a[2],time:'10:'+String(24+i)})),...typed[contactIndex]];
 msgs.forEach(m=>{const f=make('div','bubble'+(m.out?' out':''));f.append(document.createTextNode(m.text),make('small','',m.time));full.append(f);const b=make('div','preview-bubble'+(m.out?' out':''));b.append(document.createTextNode(m.text),make('time','',m.time));small.append(b);});
 full.scrollTop=full.scrollHeight;small.scrollTop=small.scrollHeight;
}
function submitMessage(input){const value=input.value.trim();if(!value||value.length>500)return;typed[contactIndex].push({text:value,out:true,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});input.value='';chat();input.focus({preventScroll:true});showToast(lang==='ru'?'Добавлено в локальное демо. Ничего не отправлено.':'Added to this local demo. Nothing was sent.');}
function renderTeam(){
 const body=$('#team-rows');body.replaceChildren();const filter=$('#role-filter').value;
 team.forEach((p,i)=>{if(filter!=='all'&&filter!==p.role)return;const tr=make('tr'),name=make('td'),box=make('div','team-person');box.append(make('span','avatar '+p.color,p.initials),make('strong','',p.name));name.append(box);const role=make('td','team-role',p.role==='Manager'?t('manager'):t('chatter'));const status=make('td');status.append(make('span','team-status'+(p.on?'':' off'),lang==='ru'?(p.on?'На смене':'Не на смене'):(p.on?'On shift':'Off shift')));const account=make('td','team-num',String(p.accounts));const switchCell=make('td');const b=make('button','shift-switch');b.type='button';b.setAttribute('role','switch');b.setAttribute('aria-checked',String(p.on));b.setAttribute('aria-label',(lang==='ru'?'Смена: ':'Shift: ')+p.name);b.dataset.member=i;b.addEventListener('click',()=>{team[i].on=!p.on;renderTeam();$('[data-member="'+i+'"]').focus({preventScroll:true});});switchCell.append(b);tr.append(name,role,status,account,switchCell);body.append(tr);});
 const count=team.filter(p=>p.on).length;$('#team-online').textContent=lang==='ru'?'На смене: '+count:count+' people on shift';$('#scene-onshift').textContent=String(count).padStart(2,'0');
 const sr=$('#scene-team');sr.replaceChildren(...team.map(p=>{const r=make('div','scene-team-row');r.append(make('span','avatar '+p.color,p.initials),make('strong','',p.name),make('small','',p.on?(lang==='ru'?'На смене':'On shift'):(lang==='ru'?'Не на смене':'Off shift')));return r;}));
}
function setLanguage(next){
 clearTimeout(toastTimer);$('#toast').classList.remove('show');
 lang=next;document.documentElement.lang=next;$$('[data-i18n]').forEach(n=>{const val=dict()[n.dataset.i18n];if(val!==undefined)n.innerHTML=val;});
 $('#lang-en').classList.toggle('active',next==='en');$('#lang-ru').classList.toggle('active',next==='ru');$('#language-toggle').setAttribute('aria-label',next==='en'?'Switch to Russian':'Switch to English');
 $('#chat-input').placeholder=next==='ru'?'Написать в демо…':'Type a demo message…';$('#preview-input').placeholder=next==='ru'?'Написать…':'Type a message…';
 conversations();chat();renderTeam();updatePeriod();setTab(activeTab);layoutArt();renderBenefits();
}
function closeMenu(){$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
function openInfo(name,opener){
 if(!['pricing','download','questions','help','login'].includes(name))return;returnFocus=opener||document.activeElement;closeMenu();
 $$('[data-info-content]').forEach(n=>n.hidden=n.dataset.infoContent!==name);
 $('#info-dialog').setAttribute('aria-labelledby',name+'-title');if(!$('#info-dialog').open)$('#info-dialog').showModal();document.body.classList.add('modal-open');
}
function openDemo(tab='overview',opener){
 const candidate=opener||document.activeElement;if(!candidate.closest('dialog'))returnFocus=candidate;
 if($('#info-dialog').open)$('#info-dialog').close();closeMenu();setTab(tab);if(!$('#demo-dialog').open)$('#demo-dialog').showModal();document.body.classList.add('modal-open');$('#tab-'+tab).focus({preventScroll:true});chat();
}
$$('[data-info]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openInfo(b.dataset.info,b);}));
$$('[data-demo]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openDemo(b.dataset.demo,b);}));
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('dialog').forEach(dialog=>{
 dialog.addEventListener('close',()=>{if(!$('dialog[open]')){document.body.classList.remove('modal-open');if(returnFocus?.isConnected&&!returnFocus.closest('dialog'))returnFocus.focus({preventScroll:true});}});
 dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
});
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
$$('[data-scene-view]').forEach(b=>b.addEventListener('click',()=>setScene(b.dataset.sceneView,b)));
$$('[data-contact]').forEach(b=>b.addEventListener('click',()=>selectContact(Number(b.dataset.contact))));
$('#date-range').addEventListener('change',e=>{period=e.target.value;updatePeriod();});$('#scene-period').addEventListener('change',e=>{period=e.target.value;updatePeriod();});
$('#role-filter').addEventListener('change',renderTeam);
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();submitMessage($('#chat-input'));});
$('#preview-compose').addEventListener('submit',e=>{e.preventDefault();submitMessage($('#preview-input'));});
$('#reset-demo').addEventListener('click',()=>{typed=contacts.map(()=>[]);team=initialTeam.map(x=>({...x}));contactIndex=0;period='30';$('#role-filter').value='all';$('#chat-input').value='';$('#preview-input').value='';conversations();chat();renderTeam();updatePeriod();setTab('overview');showToast(lang==='ru'?'Демо сброшено. Изменения очищены.':'Demo reset. Changes cleared.');});
$('#language-toggle').addEventListener('click',()=>setLanguage(lang==='en'?'ru':'en'));
$('#menu-toggle').addEventListener('click',()=>{const open=$('#main-nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});document.addEventListener('click',e=>{if(!e.target.closest('.site-header'))closeMenu();});
$('.demo-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const names=['overview','inbox','team'];let i=names.indexOf(e.target.dataset.tab||activeTab);i=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:-1)+3)%3;setTab(names[i],true);});
function layoutArt(){
 const width=$('.masthead').clientWidth;
 if(window.innerWidth>900){$('#art-plane').style.transform='scale('+(width/1374)+')';}
 else{const scale=width/865;$('#art-plane').style.transform='translate('+(-509*scale)+'px,'+(-76*scale)+'px) scale('+scale+')';}
}
if('ResizeObserver'in window)new ResizeObserver(layoutArt).observe($('.masthead'));window.addEventListener('resize',()=>{layoutArt();if(window.innerWidth>900)closeMenu();});
// No automatic scrolling or autofocus on page load: the reference hero stays in view.

// Five benefits, one panel: v6 browsing rhythm, no repeated full-page chapters.
let selectedFeature='content';
const featureNames=[...document.querySelectorAll('#feature-tabs [data-feature]')].map(b=>b.dataset.feature);
function selectFeature(name,focus=false){
 if(!featureNames.includes(name))return;selectedFeature=name;
 $$('[data-feature]').forEach(b=>{const active=b.dataset.feature===name;b.classList.toggle('selected',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});
 $$('.feature-detail').forEach(p=>p.hidden=p.id!=='feature-panel-'+name);
 if(focus)$('#feature-tab-'+name).focus({preventScroll:true});
}
$$('[data-feature]').forEach(b=>b.addEventListener('click',()=>selectFeature(b.dataset.feature)));
$('#feature-tabs').addEventListener('keydown',e=>{
 if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();
 const i=featureNames.indexOf(selectedFeature),n=featureNames.length;
 selectFeature(featureNames[e.key==='Home'?0:e.key==='End'?n-1:(i+(e.key==='ArrowRight'?1:-1)+n)%n],true);
});
$$('[data-workflow]').forEach(b=>b.addEventListener('click',()=>{
 $$('[data-workflow]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));
 $('#workflow-bumps').hidden=b.dataset.workflow!=='bumps';$('#workflow-hunter').hidden=b.dataset.workflow!=='hunter';
}));
const bl=(en,ruText)=>lang==='ru'?ruText:en;
const money=n=>'$'+n.toLocaleString('en-US');
const bIcon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><use href="#i-${n}"></use></svg>`;
const bAssets={editorial:'assets/preview-editorial.webp',detail:'assets/preview-detail.webp',summit:'assets/preview-summit.webp'};
const initialMedia=[
 {id:'evening',name:['Evening set','Вечерняя подборка'],type:'PHOTO',asset:'editorial',sales:14,revenue:420,unsorted:true,used:true},
 {id:'portrait',name:['Portrait series','Портретная серия'],type:'PHOTO',asset:'detail',sales:0,revenue:0,unsorted:true,used:false},
 {id:'studio',name:['Studio cut','Студийный клип'],type:'VIDEO',asset:'editorial',sales:6,revenue:180,unsorted:true,used:true},
 {id:'preview',name:['A little preview','Небольшой тизер'],type:'VIDEO',asset:'summit',sales:0,revenue:0,unsorted:false,used:true},
 {id:'afterhours',name:['After hours','После съёмки'],type:'PHOTO',asset:'detail',sales:12,revenue:360,unsorted:false,used:true}
];
let demoMedia=initialMedia.map(x=>({...x})),vaultFilter='unsorted',mediaSelection=new Set(['evening']),vaultMoved=0;
function renderVault(){
 $('#unsorted-count').textContent=demoMedia.filter(x=>x.unsorted).length;
 $$('[data-vault-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vaultFilter===vaultFilter)));
 let rows=demoMedia.filter(x=>vaultFilter!=='unsorted'||x.unsorted);
 if(vaultFilter==='revenue')rows.sort((a,b)=>b.revenue-a.revenue);
 $('#vault-rows').innerHTML=rows.length?rows.map(x=>`<label class="b-media-row${mediaSelection.has(x.id)?' picked':''}"><span class="b-media-name"><input type="checkbox" data-media="${x.id}" ${mediaSelection.has(x.id)?'checked':''} aria-label="${bl('Select','Выбрать')} ${x.name[lang==='ru'?1:0]}"><img src="${bAssets[x.asset]}" alt="" width="40" height="50"><span><strong>${x.name[lang==='ru'?1:0]}</strong><small>${x.type} <i>·</i> ${x.unsorted?bl('Unsorted','Без папки'):bl('Ready folder','В папке «Готово»')}</small></span></span><span class="b-media-sales">${x.sales}</span><span class="b-media-revenue">${money(x.revenue)}</span></label>`).join(''):`<div class="b-empty">${bIcon('check')}<strong>${bl('Nothing left unsorted.','Неразобранного не осталось.')}</strong><span>${bl('Open All media to see the organized files.','Откройте «Все медиа», чтобы увидеть файлы.')}</span></div>`;
 $('#vault-selection').textContent=bl(`${mediaSelection.size} selected`,`${mediaSelection.size} выбрано`);
 const canMove=[...mediaSelection].some(id=>demoMedia.find(x=>x.id===id)?.unsorted);
 $('#vault-organize').disabled=!canMove;
 $('#vault-status').textContent=vaultMoved?bl(`${vaultMoved} file(s) organized in this demo. No real media changed.`,`Разобрано файлов в демо: ${vaultMoved}. Реальные медиа не менялись.`):bl('Select media, then put it into a folder.','Выберите медиа и добавьте в папку.');
}
$$('[data-vault-filter]').forEach(b=>b.addEventListener('click',()=>{vaultFilter=b.dataset.vaultFilter;mediaSelection.clear();renderVault();}));
$('#vault-rows').addEventListener('change',e=>{const id=e.target.dataset.media;if(!id)return;e.target.checked?mediaSelection.add(id):mediaSelection.delete(id);renderVault();$(`[data-media="${id}"]`)?.focus({preventScroll:true});});
$('#vault-organize').addEventListener('click',()=>{let n=0;demoMedia.forEach(x=>{if(mediaSelection.has(x.id)&&x.unsorted){x.unsorted=false;n++;}});vaultMoved+=n;mediaSelection.clear();renderVault();});
$('#vault-reset').addEventListener('click',()=>{demoMedia=initialMedia.map(x=>({...x}));vaultFilter='unsorted';vaultMoved=0;mediaSelection=new Set(['evening']);renderVault();});

const topicNames={foot:['Foot content','Фут-контент'],roleplay:['Roleplay','Ролевые сюжеты'],photos:['Photo sets','Фотосеты']};
const exampleFans=[
 {name:'James M.',initials:'JM',spend:100,likes:['foot'],no:['roleplay'],why:{foot:['Asked for foot content','Просил фут-контент'],roleplay:['Explicitly declined this format','Явно отказался от формата']}},
 {name:'Leo R.',initials:'LR',spend:100,likes:['roleplay'],no:['foot'],why:{roleplay:['Asked for a roleplay set','Просил ролевую подборку'],foot:['Explicitly declined this format','Явно отказался от формата']}},
 {name:'Daniel T.',initials:'DT',spend:80,likes:['photos'],no:[],why:{photos:['Asked about new photo sets','Спрашивал о новых фотосетах']}},
 {name:'Alex K.',initials:'AK',spend:120,likes:[],no:[],why:{}}
];
let chosenTopic='foot';
function renderAudience(){
 $$('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===chosenTopic)));
 let included=0;
 $('#audience-rows').innerHTML=exampleFans.map(f=>{
  const rejected=f.no.includes(chosenTopic),fits=!rejected&&f.likes.includes(chosenTopic);if(fits)included++;
  const state=fits?'match':rejected?'refused':'unknown';
  let why=f.why[chosenTopic]?.[lang==='ru'?1:0]||bl('No expressed interest in this topic','Нет выраженного интереса к теме');
  if(!f.likes.length&&!f.no.length)why=bl('Preference not known','Предпочтение неизвестно');
  const badge=fits?bl('MATCH','ПОДХОДИТ'):rejected?bl('EXCLUDED','ИСКЛЮЧЁН'):bl('NOT SELECTED','НЕ ВЫБРАН');
  return `<div class="b-fan-match ${state}"><span class="b-letter-avatar">${f.initials}</span><div><strong>${f.name} <small>${money(f.spend)} ${bl('spent','потратил')}</small></strong><p>${why}</p></div><span class="b-match-state">${bIcon(fits?'check':rejected?'x':'minus')}<span>${badge}</span></span></div>`;
 }).join('');
 $('#audience-total').textContent=bl(`${included} of ${exampleFans.length} selected`,`${included} из ${exampleFans.length} выбрано`);
}
$$('[data-topic]').forEach(b=>b.addEventListener('click',()=>{chosenTopic=b.dataset.topic;renderAudience();}));
const shiftExamples={morning:{median:['2m 14s','2м 14с'],p90:['7m 38s','7м 38с'],waiting:7,posts:6,stories:12,human:284,auto:79,hours:'09:00 — 17:00',complete:true},evening:{median:['3m 06s','3м 06с'],p90:['9m 12s','9м 12с'],waiting:11,posts:4,stories:8,human:198,auto:46,hours:'17:00 — 01:00',complete:false}};
function renderShift(){
 const d=shiftExamples[$('#benefit-shift').value];
 $('#t-median').textContent=d.median[lang==='ru'?1:0];$('#t-p90').textContent=d.p90[lang==='ru'?1:0];
 for(const k of ['waiting','posts','stories','human','auto'])$('#t-'+k).textContent=String(d[k]).padStart(2,'0');
 $('#shift-caption').textContent=d.hours+' · '+bl('example shift','пример смены');
 $('#human-bar').style.width=(d.human/(d.human+d.auto)*100)+'%';$('#auto-bar').style.width=(d.auto/(d.human+d.auto)*100)+'%';
 const status=$('#team-data-state');status.classList.toggle('partial',!d.complete);
 status.innerHTML=bIcon(d.complete?'check':'clock')+`<span>${d.complete?bl('Example with complete coverage. Values are fictional.','Пример с полным покрытием. Числа вымышлены.'):bl('Example with partial coverage. Do not read missing data as zero.','Пример с неполным покрытием. Нет данных — не значит ноль.')}</span>`;
}
$('#benefit-shift').addEventListener('change',renderShift);
let orderStage='creator',reminderPreview=false;
function renderOrder(){
 const stages=['brief','creator','ready','delivered'];
 $$('[data-order-stage]').forEach(b=>{b.setAttribute('aria-pressed',String(b.dataset.orderStage===orderStage));b.classList.toggle('done',stages.indexOf(b.dataset.orderStage)<=stages.indexOf(orderStage));});
 const copy={brief:['Brief recorded. Check scope, price and references with the creator.','Задание записано. Согласуйте с моделью формат, цену и референсы.'],creator:['Task handed to the creator. Deadline: tomorrow, 18:00 (example).','Задание передано модели. Срок: завтра, 18:00 (пример).'],ready:['Work is ready. Check the agreed payment and handover terms.','Материал готов. Проверьте согласованные условия оплаты и выдачи.'],delivered:['Delivered in this illustration. Payment records remain a separate step.','В этом примере заказ выдан. Учёт оплаты — отдельный шаг.']};
 $('#order-stage-status').innerHTML=bIcon(orderStage==='delivered'?'check':'clock')+`<p>${copy[orderStage][lang==='ru'?1:0]}</p>`;
 $('#order-reminder').disabled=orderStage==='delivered';
 $('#order-reminder-result').textContent=reminderPreview?bl('Example reminder: Ava, order #1042 is due tomorrow at 18:00. Brief and references are attached. Nothing was sent.','Пример напоминания: Ava, заказ #1042 нужен завтра к 18:00. Задание и референсы приложены. Ничего не отправлено.'):'';
}
$$('[data-order-stage]').forEach(b=>b.addEventListener('click',()=>{orderStage=b.dataset.orderStage;reminderPreview=false;renderOrder();}));
$('#order-reminder').addEventListener('click',()=>{reminderPreview=true;renderOrder();});
let boundaryCreator='ava';
function renderBoundaries(){
 const noCalls=boundaryCreator==='ava';
 $$('[data-boundary-creator]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.boundaryCreator===boundaryCreator)));
 $('#boundary-rules').innerHTML=noCalls?`<p><span class="b-rule-dot"></span><strong>${bl('Video calls: not offered.','Видеозвонки: не предлагает.')}</strong></p><p>${bl('Photo customs: only with a confirmed brief.','Фотокастомы: только с согласованным заданием.')}</p>`:`<p><span class="b-rule-dot yes"></span><strong>${bl('Video calls: by prior agreement.','Видеозвонки: по согласованию.')}</strong></p><p>${bl('Time and format must be agreed before any promise.','Время и формат согласовываются до обещания.')}</p>`;
 const w=$('#boundary-warning');w.classList.toggle('possible',!noCalls);
 w.innerHTML=bIcon(noCalls?'shield':'check')+`<div><strong>${noCalls?bl('Ava does not offer video calls.','Ava не предлагает видеозвонки.'):bl('No conflict with this listed condition.','Нет противоречия с указанным условием.')}</strong><p>${noCalls?bl('Do not promise this service or accept payment for it.','Не обещайте эту услугу и не принимайте за неё оплату.'):bl('Confirm Sofia’s availability and terms. This is not blanket permission to sell.','Подтвердите доступность и условия Sofia. Это не безусловное разрешение на продажу.')}</p><small>${bl('Scenario preview · planned feature','Иллюстрация сценария · функция планируется')}</small></div>`;
}
$$('[data-boundary-creator]').forEach(b=>b.addEventListener('click',()=>{boundaryCreator=b.dataset.boundaryCreator;renderBoundaries();}));
